public int Trap(int[] h) {
    int n = h.Length, total = 0;
    var maxLeft = new int[n];
    var maxRight = new int[n];
    for (int i = 0; i < n; i++) maxLeft[i] = Math.Max(i > 0 ? maxLeft[i - 1] : 0, h[i]);
    for (int i = n - 1; i >= 0; i--) maxRight[i] = Math.Max(i < n - 1 ? maxRight[i + 1] : 0, h[i]);
    for (int i = 0; i < n; i++) total += Math.Min(maxLeft[i], maxRight[i]) - h[i];
    return total;
}

